3 · Vegetation structure


Show code
ranking_path &lt;- "data/results/unified_park_ranking.rds"
rds_path     &lt;- "data/results/ugs_analysis_10m_utm.rds"
csv_path     &lt;- "data/results/FIELD_SAMPLING_FINAL_REPORT.csv"

veg_cols &lt;- c("mean_woody", "mean_grass", "woody_ratio", "grass_ratio",
              "structure_cat", "stgohot_decile_mean", "condition",
              "sampling_priority", "ndvi_mean", "ndvi_decile",
              "woody_decile", "temp_decile", "priority_score")

if (file.exists(ranking_path)) {
  veg &lt;- readRDS(ranking_path) |&gt;
    dplyr::select(park_id, dplyr::any_of(veg_cols))
} else if (file.exists(rds_path)) {
  veg &lt;- readRDS(rds_path) |&gt;
    sf::st_drop_geometry() |&gt;
    dplyr::select(park_id, dplyr::any_of(veg_cols))
} else {
  veg &lt;- tibble::tibble(park_id = thermal_df$park_id)
}

# Add missing columns as NA
for (col in veg_cols) {
  if (!col %in% names(veg)) veg[[col]] &lt;- NA
}

# Plain dataframe join
full_df &lt;- dplyr::left_join(thermal_df, veg, by = "park_id")

# Structural fallback
full_df$structure_cat &lt;- dplyr::coalesce(
  full_df$structure_cat,
  dplyr::case_when(
    full_df$greenspace_type == "Lawn Park" ~ "High Herbaceous Cover",
    full_df$greenspace_type == "Roadside"  ~ "High Herbaceous Cover",
    TRUE                                   ~ NA_character_
  )
)

sprintf("Parks with structure data: %d | unclassified: %d",
        sum(!is.na(full_df$structure_cat)),
        sum( is.na(full_df$structure_cat)))


